// Velure - choose this week's topic and build the prompt.
// Topics rotate by ISO week so the same one never repeats back to back.
const TOPICS = [
  'seasonal skin in the Arizona desert (dryness, sun, hydration)',
  'how a facial differs from a medical-grade treatment',
  'what to expect at a first consultation',
  'daily SPF habits that actually stick',
  'collagen: what it is and what helps it',
  'aftercare basics after microneedling or laser',
  'myths about injectables and natural results',
  'building a simple evening routine',
];
const previewOnly = !!($input.first().json || {}).previewOnly;

// ISO week number (Phoenix wall time, UTC-7)
const d = new Date(Date.now() - 7 * 3600 * 1000);
const t = new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate()));
const dayNum = t.getUTCDay() || 7;
t.setUTCDate(t.getUTCDate() + 4 - dayNum);
const yearStart = new Date(Date.UTC(t.getUTCFullYear(), 0, 1));
const week = Math.ceil(((t - yearStart) / 86400000 + 1) / 7);
const topic = TOPICS[week % TOPICS.length];

const system = "You write \"The Velure Letter\", a short weekly email from Velure Med Spa (Scottsdale, Arizona).\nVoice: calm, precise, warm, never salesy, no exclamation marks, no emojis. Clinical credibility with a soft hand.\nWrite about the single topic you are given. Do not mention that it was assigned.\nRules: 180-260 words in total. Structure: a title (max 8 words), one short intro paragraph, three short points each with a bold lead-in (a few words), and one closing line inviting readers to book a consultation at Velure.\nNever give individual medical advice; recommend a consultation for personal questions. Do not invent prices, discounts, statistics or clinical claims you cannot stand behind. Do not name products or brands.\nReturn ONLY a JSON object, with no code fences and no commentary: {\"subject\": \"...\", \"title\": \"...\", \"intro\": \"...\", \"points\": [{\"lead\": \"...\", \"text\": \"...\"}, {\"lead\": \"...\", \"text\": \"...\"}, {\"lead\": \"...\", \"text\": \"...\"}], \"closing\": \"...\"}";
const userPrompt = `Write this week's letter. Topic: ${topic}. Return only the JSON object.`;
return [{ json: { previewOnly, week, topic, system, userPrompt } }];

// Velure - validate Claude's JSON and build the letter HTML.
// Shared Velure email shell (inline styles only — email clients ignore <style> blocks)
const shell = (title, bodyHtml) => `<!doctype html><html><body style="margin:0;padding:0;background:#FAF6F1;">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#FAF6F1;padding:40px 16px;">
<tr><td align="center">
<table role="presentation" width="560" cellpadding="0" cellspacing="0" style="max-width:560px;width:100%;background:#FFFFFF;border:1px solid #EFE6DA;border-radius:14px;">
<tr><td style="padding:40px 40px 8px 40px;font-family:Georgia,'Times New Roman',serif;font-size:26px;letter-spacing:-0.5px;color:#2B2420;">Velure</td></tr>
<tr><td style="padding:0 40px;font-family:Helvetica,Arial,sans-serif;font-size:10px;letter-spacing:3px;text-transform:uppercase;color:#B08968;">Med Spa &middot; Scottsdale</td></tr>
<tr><td style="padding:28px 40px 0 40px;"><div style="height:1px;background:#EFE6DA;line-height:1px;">&nbsp;</div></td></tr>
<tr><td style="padding:28px 40px 0 40px;font-family:Georgia,'Times New Roman',serif;font-size:24px;line-height:1.25;color:#2B2420;">${title}</td></tr>
<tr><td style="padding:16px 40px 36px 40px;font-family:Helvetica,Arial,sans-serif;font-size:15px;line-height:1.65;color:#4A3F39;">${bodyHtml}</td></tr>
</table>
<table role="presentation" width="560" cellpadding="0" cellspacing="0" style="max-width:560px;width:100%;">
<tr><td style="padding:20px 8px;font-family:Helvetica,Arial,sans-serif;font-size:11px;line-height:1.6;color:#8A7D74;text-align:center;">
Velure Med Spa &middot; 1200 Desert Bloom Ave, Scottsdale, AZ &middot; (480) 555-0142<br>
Velure is a fictional brand created as a demonstration project by <a href="https://thaus.co" style="color:#8A7D74;">Thaus</a>.
</td></tr></table>
</td></tr></table></body></html>`;
const esc = (v) => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const row = (k, v) => `<tr><td style="padding:6px 0;color:#8A7D74;width:120px;vertical-align:top;">${k}</td><td style="padding:6px 0;color:#2B2420;">${v}</td></tr>`;

const reply = $input.first().json;
const raw = (reply.content || []).map((c) => c.text || '').join('').trim();
if (!raw) throw new Error('Claude returned no text: ' + JSON.stringify(reply).slice(0, 300));

// Tolerate code fences or a stray sentence around the JSON.
const start = raw.indexOf('{'), end = raw.lastIndexOf('}');
if (start < 0 || end < start) throw new Error('No JSON object in Claude reply: ' + raw.slice(0, 200));
let letter;
try { letter = JSON.parse(raw.slice(start, end + 1)); }
catch (e) { throw new Error('Claude JSON did not parse: ' + e.message); }

// Voice rules enforced in code, not just in the prompt.
const clean = (v) => String(v ?? '')
  .replace(/!/g, '.')
  .replace(/[\u{1F000}-\u{1FFFF}\u{2600}-\u{27BF}\u{FE0F}]/gu, '')
  .replace(/\s+/g, ' ')
  .trim();

const subject = clean(letter.subject);
const title = clean(letter.title);
const intro = clean(letter.intro);
const closing = clean(letter.closing);
const points = Array.isArray(letter.points) ? letter.points.map((p) => ({ lead: clean(p && p.lead), text: clean(p && p.text) })) : [];

if (!subject || !title || !intro || !closing) throw new Error('Letter is missing subject, title, intro or closing.');
if (points.length !== 3 || points.some((p) => !p.lead || !p.text)) throw new Error('Letter must have exactly 3 points with lead and text.');

const words = [title, intro, closing, ...points.map((p) => p.lead + ' ' + p.text)].join(' ').split(/\s+/).length;
if (words < 120 || words > 330) throw new Error(`Letter length looks wrong (${words} words); not sending.`);

const pointsHtml = points.map((p) =>
  `<p style="margin:0 0 14px 0;"><strong style="color:#2B2420;">${esc(p.lead)}.</strong> ${esc(p.text)}</p>`).join('');

const html = shell(
  esc(title),
  `<p style="margin:0 0 20px 0;">${esc(intro)}</p>
   ${pointsHtml}
   <p style="margin:22px 0 24px 0;">${esc(closing)}</p>
   <p style="margin:0 0 28px 0;"><a href="https://velure-medspa.vercel.app/#book" style="display:inline-block;padding:14px 28px;background:#2B2420;color:#FAF6F1;border-radius:999px;text-decoration:none;font-family:Helvetica,Arial,sans-serif;font-size:14px;">Book a consultation</a></p>
   <p style="margin:0;color:#2B2420;">With care,<br>The Velure team</p>
   <p style="margin:28px 0 0 0;font-size:12px;color:#8A7D74;">You are receiving this because you subscribed to The Velure Letter on our website. <a href="%%UNSUB%%" style="color:#8A7D74;">Unsubscribe</a> at any time. This letter is general information, not personal medical advice.</p>`
);

return [{ json: { subject, html, words } }];

// Velure - one email per active subscriber (or just the owner in preview mode).

// IMPORTANT: use the SAME secret as in the Subscribe and Unsubscribe workflows,
// otherwise the unsubscribe link in the letter will be rejected.
const UNSUB_SECRET = 'REPLACE_WITH_A_LONG_RANDOM_SECRET';
const OWNER = 'owner@example.com';
// Pure-JS HMAC-SHA256 (no require): n8n's Code node blocks built-in modules by default.
const hmacHex = (key, msg) => {
  const K = [0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2];
  const utf8 = (s) => Array.from(unescape(encodeURIComponent(s)), (c) => c.charCodeAt(0));
  const sha = (bytes) => {
    const H = [0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19];
    const l = bytes.length, m = bytes.concat([0x80]);
    while (m.length % 64 !== 56) m.push(0);
    const bits = l * 8;
    for (let i = 7; i >= 0; i--) m.push(i > 3 ? 0 : (bits >>> (i * 8)) & 255);
    const rr = (x, n) => (x >>> n) | (x << (32 - n));
    for (let o = 0; o < m.length; o += 64) {
      const w = [];
      for (let i = 0; i < 16; i++) w[i] = (m[o+i*4] << 24) | (m[o+i*4+1] << 16) | (m[o+i*4+2] << 8) | m[o+i*4+3];
      for (let i = 16; i < 64; i++) {
        const s0 = rr(w[i-15],7) ^ rr(w[i-15],18) ^ (w[i-15] >>> 3);
        const s1 = rr(w[i-2],17) ^ rr(w[i-2],19) ^ (w[i-2] >>> 10);
        w[i] = (w[i-16] + s0 + w[i-7] + s1) | 0;
      }
      let [a,b,c,d,e,f,g,h] = H;
      for (let i = 0; i < 64; i++) {
        const t1 = (h + (rr(e,6) ^ rr(e,11) ^ rr(e,25)) + ((e & f) ^ (~e & g)) + K[i] + w[i]) | 0;
        const t2 = ((rr(a,2) ^ rr(a,13) ^ rr(a,22)) + ((a & b) ^ (a & c) ^ (b & c))) | 0;
        h = g; g = f; f = e; e = (d + t1) | 0; d = c; c = b; b = a; a = (t1 + t2) | 0;
      }
      H[0]=(H[0]+a)|0; H[1]=(H[1]+b)|0; H[2]=(H[2]+c)|0; H[3]=(H[3]+d)|0;
      H[4]=(H[4]+e)|0; H[5]=(H[5]+f)|0; H[6]=(H[6]+g)|0; H[7]=(H[7]+h)|0;
    }
    return H.flatMap((x) => [x >>> 24, (x >>> 16) & 255, (x >>> 8) & 255, x & 255]);
  };
  let k = utf8(key);
  if (k.length > 64) k = sha(k);
  while (k.length < 64) k.push(0);
  const inner = sha(k.map((x) => x ^ 0x36).concat(utf8(msg)));
  const out = sha(k.map((x) => x ^ 0x5c).concat(inner));
  return out.map((x) => x.toString(16).padStart(2, '0')).join('');
};

const { subject, html } = $('Build Letter').first().json;
const previewOnly = !!$('Pick Topic').first().json.previewOnly;

const seen = new Set();
let recipients = [];
if (previewOnly) {
  recipients = [OWNER];
} else {
  for (const item of $input.all()) {
    const j = item.json || {};
    const e = String(j.property_email || (j.properties && j.properties.Email && j.properties.Email.email) || '').trim().toLowerCase();
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(e) || seen.has(e)) continue;
    seen.add(e);
    recipients.push(e);
  }
}

return recipients.map((email) => {
  const token = hmacHex(UNSUB_SECRET, email).slice(0, 32);
  const link = `https://your-n8n-instance.example.com/webhook/velure-unsubscribe?email=${encodeURIComponent(email)}&token=${token}`;
  return { json: { email, subject: previewOnly ? `[Preview] ${subject}` : subject, html: html.replace('%%UNSUB%%', link) } };
});
